ValidationRule.errorConditionFormula:
OR(
    AND(
        OR(ISPICKVAL(Estado__c, "Encolada"), ISPICKVAL(Estado__c, "En curso")),
        NOT(ISBLANK(Finalizacion__c))
    ),
    AND(
        NOT(OR(ISPICKVAL(Estado__c, "Encolada"), ISPICKVAL(Estado__c, "En curso"))),
        ISBLANK(Finalizacion__c)
    )
)
